INSERT INTO Definition (word_id, language_id, pos_id, definition, example)
VALUES (15705,3,1,'သုံးဆဲ့နှစ်လုံးမြောက်မွန်ဗျည်း။',NULL)
,(15706,3,16,'တစ်သောင်း။','‘လက်’ ရှု။')
,(15707,3,4,'မျက်ကလူးဆန်ပျာဖြစ်သည်။','“မတ်ဂှ်ဠိၚ်ဠံၚ်၊ ညံၚ်ဒြာဲဒးဇာ” (အကြီုနမော။ စန္ဒိမာစာရ) = “ပိုက်ကွန်­မိသောသမင်ကဲ့သို့ (ကြောက်၍) မျက်ကလူးဆန်ပျာဖြစ်သည်။”')
,(15708,3,4,'(မိန်းမ) ဣန္ဒြေမရဖြစ်သည်။ ဆတ်စလူးဖြစ်သည်။ အရှက်နည်းပါးသည်။',NULL)
,(15709,3,1,'ချက်။','‘တၠိုတ်’ ရှု။')
,(15710,3,4,'လိမ်ညာသည်။',NULL)
,(15711,3,4,'(ကလေးငိုအောင်၊ စိတ်ဆိုးအောင်) စသည်။ ကျီစယ်သည်။','“လ္ပဠဝ်ဝေၚ်ကောန်ၚာ်ညိ။” = “ကလေးငိုအောင် မစ၊ပါနှင့်။”')
,(15712,3,1,'သုံးဆဲ့သုံးလုံးမြောက်မွန်ဗျည်း။',NULL)
,(15713,3,4,'သိဒ္ဓိတၚ်သည်။','“စဝ်ကပေါဝ်မ္ဂး ဒးၜရောၚ်။” = “ကၚ်ပွန်းတပ်လျှင် သိဒ္ဓိတၚ်ရမည်။”')
,(15714,3,16,'နှစ်ခု။','ၜါစှ်ော = နှစ်ဆယ်။')
,(15714,3,7,'နှင့်။ နှင့်တကွ။ နှစ်ဦးအတူတကွ။','“အဲၜါနာဲအဲ၊ နဲဗီုဂှ်ရ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “ငါနှင့်ချစ်သူသခင်သည် ထိုနည်းပုံပမာပင်တည်း။”')
,(15715,3,4,'နားငြီးသည်။','‘ၜိုဟ်ရိုဟ်’ ရှု။')
,(15716,3,5,'နှစ်ခြမ်း။ နှစ်စိတ်။ နှစ်ဖွဲ့။ (ကွဲသည်)','“သြိုဟ်မိဒကး၊ ၜါလွးရရဴ။” (လိက်ရတနပဇ္ဇောတ) = “မယ့်ရၚ်နှစ်ခြမ်းကွဲသွားအံ့သကဲ့သို့ဖြစ်၏။”')
,(15717,3,1,'မြစ်။ ပင်လယ်။','ၜဳဇၞော် = ပင်လယ်သမုဒ္ဒရာ။')
,(15718,3,4,'တွေဝေသည်။ မိန်းမူးသည်။','‘တ္ၜူမာဲ’ ရှု။')
,(15719,3,1,'တစ်ပဲ။ တစ်ကျပ်၏တစ်ဆဲ့ခြောက်ပုံတစ်ပုံ။','“(ကဝွံ) ဒှ်ရနာဲပိုဲကေတ်ဂှ် ထပှ်ၜဲပိုဲသကေတ်ရ” တမ္ၚာတံဂး။ (ဇ—၂၈၈။ အစွောံ။) = “(ဤငါးကို) သင်တို့သည်မူကား ခုနစ်ပဲမျှပေး၍ ယူကုန်လော့” ဟုတံငါတို့သည် ဆိုကုန်၏။ (ညောင်ကန်) || “ညးဗၞိက်အလီ၊ သမ္တီမူၜဲ။” (လိက်လက္ခဏပိ) = “မူးပဲကိုပင်မှတ်သားသော ကုန်သည်အလိမ်။”')
,(15720,3,1,'ပဲသီး။ ပဲတောင့်။',NULL)
,(15721,3,1,'ပဲခြမ်း။',NULL)
,(15722,3,1,'ပဲပင်ပေါက်။',NULL)
,(15723,3,1,'ကုလားပဲ။ (ပါဠိ—ခဏ္ဍိက)',NULL)
,(15724,3,1,'ပဲပုစွန်။ (ပါဠိ—စူနိမ္ပာ','သေဝါလ)')
,(15725,3,1,'မတ်ပဲ။ မာသ်ပဲ။ ပဲလွန်းကြီး။ (အစေ့နက်သောပဲတစ်မျိုး) (ပါဠိ—မာသ)',NULL)
,(15726,3,1,'ပဲလွန်းငယ်။',NULL)
,(15727,3,1,'ပဲပိစပ်။ (ပါဠိ—ကုလတ္ထ)',NULL)
,(15728,3,1,'မြေပဲ။',NULL)
,(15729,3,1,'ပဲတောင့်။',NULL)
,(15730,3,1,'ပဲနောက်။ (ပါဠိ—မုဂ္ဂ)','“ယွံတြဗမၞး၊ လ္ၚဴကီု ၜဲမုက်ကီု သ္ၚုကီု ဍေံဟၟဲကုပိုဲဗတာဲရ။” (ဇ—၃၁၆။ အစွောံ။) = “ပုဏ္ဏား၊ ယုန်အား နှမ်းတို့သည် မရှိကုန်။ ပဲနောက်တို့သည် မရှိကုန်။ ဆန်တို့သည် မရှိကုန်။” (ညောင်ကန်)')
,(15731,3,1,'ပဲကြီး။ (ဇ—၂၄၁။ အစွောံ။ ညောင်ကန်။)',NULL)
,(15732,3,1,'ပဲစင်းခုန်။ (= ပဲစင်းၚုံ?) (ပါဠိ—အာဎကဳ','ကက္ခဳ/တုဝရိကာ)')
,(15733,3,1,'စားတော်ပဲ။ (ပါဠိ—ကလာယ)',NULL)
,(15734,3,1,'ရုံးပတီသီး။',NULL)
,(15735,3,1,'ခွေးလှေးယားပင်။ ခွေးလှေးယားသီး။',NULL)
,(15736,3,1,'ကြံ။','ဍာ်ၜဴ = ကြံရည်။ || ‘က္ၜဴ’ ရှု။')
,(15737,3,4,'ပလုတ်ကျင်းသည်။ ခံတွင်းဆေးသည်။','‘က္ၜဴပါၚ်’ ရှု။ || ဍာ်ၜဴပါၚ် = လုပ်ဆေးရေ။ (ပါဠိ—ဥစ္ဆိဋ္ဌောဒက)')
,(15738,3,4,'၁။ လဲသည်။','ၜးဂၠိက်ယာတ် = အဝတ်အစားလဲသည်။ || ၜးပလောအ် = အင်းကျီလဲသည်။')
,(15738,3,4,'၂။ လွတ်မြောက်သည်။','“(တြုံမွဲဂှ်) ဟိုတ်နူမမှာအာဒုဟ် ပ္ဍဲကောန်သမ္ဘာညးမွဲဝါတုဲ စုတိဒးဒုၚ်တဴနရက်ရ။ ၜးတိုန်ကၠုၚ်နူနရက်ဂှ်တုဲ ၜိုန်က္တဵုဒှ်မၞိဟ်ကီုလေဝ် ဒးဒှ်ဒၟံၚ်ဘဝမၞိဟ်ဗြဴ စဵုကဵုစှ်ပန်ဘဝရ။” (သၚ်္ခါရဘေဒနဳ။ ဝိန္ဒသာရ။) = “တစ်ယောက်သောယောကျာ်းသည် သူတစ်ပါးသားမယားကို တစ်ကြိမ်ပြစ်မှားထားခြင်းကြောင့် စုတေ၍ငရဲခံရ၏။ ငရဲမှလွတ်ပြီး လူဖြစ်သော်လည်းမိန်းမအဖြစ်ဖြင့် တစ်ဆဲ့လေးဘဝဖြစ်ရ၏။”')
,(15739,3,4,'ဘဝပြောင်းသည်။ သေလွန်သည်။','“ၜးဘဝတုဲ၊ ဟွံသၞုဲဂၠိ။ ဒးစှ်ေစိန်ဂၠက်၊ နရက်ကုမ္ဘိ။” (လိက်လက္ခဏပိ) = “သေလွန်ဘဝပြောင်းသောအခါ မလွဲမသွေ လောဟကုမ္ဘိငရဲ­ကျ၍ ပူလောင်ခံစားရ၏။” || “ဂွံပ္တုဲဒါန၊ သဳလဒမၠိ။ ၜးဘဝပၠန်၊ တ္ၚဲသ္ကန်ကလိ။ ထာန်ဒုဂ္ဂတိ၊ နတ္ထိဟွံဒှ်။ သုဂ္ဂတိဂှ်၊ ပြဟ်ရောၚ်ဂွံအာ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “ဒါနပြုထား သီလစောင့်ထားသူသည် သေလွန်သောနေ့ ဘဝပြောင်းသောအခါ ဒုဂ္ဂတိဘုံသို့ မလားရောက်ရ၊ သုဂ္ဂတိဘုံသို့သာလျှင် လျင်မြန်စွာလား၏။”')
,(15740,3,4,'(အဝတ်အစား) လဲသည်။','‘ကဵုၜးလှာဲဂၠိက်ယာတ်တၟိတုဲ—။’ (ဇ—၄၄၅။ အစွောံ။) = ‘အဝတ်အစားသစ်ကို လဲစေ၍—။’ || “ဗလိုပ်ဖုံတုဲဂ္ညိ၊ ၜးလှာဲကြိယာ။” (လိက်ဇိဝှစက္က) = “ရေချိုးပြီးနောက် အဝတ်အစားလဲ၏။”')
,(15741,3,4,'(ရေချိုးရန်) ရေသနုပ်ကိုဝတ်သည်။','“ဣသိၜးသၞုက် စွံလဝ်သပိုၚ် မ္ၚးပနနသာဂှ်တုဲစှ်ေဟုံဍာ်ရ။” (ဇ—၁၅၄။ အစွောံ။) = “(ရသေ့သည်) ရေသနုပ်ကိုဝတ်၍ လျှော်တေသင်္ကန်းကို (ကျောင်းပြင်­) ထားပြီးလျှင် (ရေဆင်းချိုး၏။)” (ညောင်ကန်)')
,(15742,3,4,'ထွက်ခွါသွားသည်။',NULL)
,(15743,3,4,'သေလွန်သည်။ ဘဝတစ်ပါးသို့ပြောင်းသည်။','“ကုသဵုမပ္တံဒါန်ဂှ်ပ္တုဲတုဲ ၜးအတ္တဘဴဂွံစဴစိုပ်ဍုၚ်သွဝ်ရ။” (ဇ—၁၉။ အစွောံ။) = “ဒါနအစရှိသော ကောင်းမှုတို့ကိုပြု၍ သေလွန်ဘဝပြောင်းသောအခါ နတ်ပြည်သို့ လားရောက်၏။” || ‘အတ္တဘဴ’ (ပါသက်)')
,(15744,3,4,'သေလွန်သည်။ စုတေသည်။','“အတိုၚ်ဒလောအ်ဗ္တောန်ဗောဓိသတ်ဂှ် ညးပန်ဂှ်ဒ္ဂေတ်ဗက်တုဲ ၜးအဿဘဴ ဂွံစဴစိုပ်ဍုၚ်သွဝ်ရ။” (ဇ—၄၉ဝ။ အစွောံ။) = “ထိုလေးယောက်ကုန်သောသူတို့သည် ဘုရားလောင်း၏အဆုံးအမအတိုင်း လိုက်နာကျင့်ကြံ၍ သေလွန်သောအခါ နတ်ပြည်သို့လား၏။” || ‘ၜးအတ္တဘဴ’ နှင့်အတူတူ။ || ‘အဿဘဴ’ (သသက်)')
,(15745,3,4,'၁။ ကျော်လွန်သည်။','“ပိုဲကွာ်ၜက်အာသ္ၚိရ။” = “ငါတို့လျှောက်သည်မှာ အိမ်ကိုကျော်လွန်သွားသည်။” || “ညံၚ်ၜက်ဍုၚ်ရး၊ ပိုဲဒးအာရ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်) =“တိုင်းနိုင်ငံမှလွန်အောင် ငါတို့သွားရမည်။”')
,(15745,3,4,'၂။ ကျန်ရစ်သည်။','“ပလောအ်အဲ ၜက်ဒၟံၚ်ပ္ဍဲသ္ၚိတေံရ။” = “ကျွန်တော့်အင်းကျီ ဟိုအိမ်မှာ ကျန်ရစ်နေသည်။”')
,(15746,3,1,'ဝဥ။',NULL)
,(15747,3,4,'မည်းမှောင်သည်။','‘ဂၠုၜေက်’ ဟူ၍သုံးသည်။')
,(15748,3,1,'ဆေးလိပ်။','သုၚ်ၜံက် = ဆေးလိပ်သောက်သည်။ || “ဇဗၠုၜံက်ရ၊ စဏအဟာ။” (လိက်ဇိဝှစက္က) = “ကွမ်းယာဆေးလိပ်နှင့် အစာအာဟာရ။”')
,(15749,3,4,'(ပေါက်တူး၊ ချွန်း၊ နှုတ်သီးစသည်ဖြင့်) ပေါက်သည်။','ၜံက်တိ = မြေကြီးပေါက်သည်။ || ၜံက်စိၚ်နခၜံက် = ဆင်ကို ချွန်းဖြင့်ပေါက်သည်။ ချိတ်သည်။ || “ဂစေံဂမၠိုၚ်ဗိုၚ်ၜံက်တုဲခ္ဍာ်ဂှ်အိုတ်လမျီုဒၞာဲဂှ်ရ။” (ဇ—၃၈၄။ အစွောံ။) = “ငှက်တို့က နှုတ်သီးဖြင့် ဝိုင်းပေါက်ကြသဖြင့်ထိုကျီးသည် ထိုနေရာ­ပၚ် အသက်ကုန်၏။” || ဇြုံၜံက် = မြွေပေါက်သည်။ မြွေကိုက်သည်။ || “ကဵုဇြုံဂှ်ၜံက်ဂစိုတ်ကၠေံဗမၞးဂှ်တုဲ—။” (ဇ—၃၈၉။ အစွောံ။) = “ထိုမြွေကို ပုဏ္ဏားအားပေါက်သတ်စေပြီးလျှင်—။”')
,(15750,3,1,'ပေါက်တူး။',NULL)
,(15751,3,1,'ဆေးတံ။',NULL)
,(15752,3,1,'ကျည်ပွေ့နှင့်တွဲသုံးသောဆုံငယ်။ ငရုတ်ဆုံ။','“ထၟုက်မြေက်ကဵုၜိုက်ရ။” = “ငရုတ်သီးကို ဆုံငယ်နှင့်ထောင်းသည်။”')
,(15753,3,1,'မျှစ်။','ၜၚ်ဒုန်ကလိ = ဝါးပိုးမျှစ်။')
,(15754,3,3,'လှပသော။ တင့်တယ်သော။',NULL)
,(15755,3,4,'၁။ (ရေ) ကူးသည်။ ကူးခတ်သည်။','ၜိၚ်ဍာ် = ရေကူးသည်။')
,(15755,3,4,'၂။ အချိန်ဆွဲသည်။ကြန့်ကြာအောင်လုပ်သည်။',NULL)
,(15756,3,4,'ဒုက္ခပင်လယ်ဝေသည်။ ဒုက္ခပင်လယ်တွင် ကူးခတ်သည်။',NULL)
,(15757,3,4,'ရိုက်သည်။ ခတ်သည်။ နှက်သည်။','ၜုၚ်ကဵုရိ = ကျည်ပွေ့နှင့်ရိုက်သည်။ || ၜုၚ်ကၚ် =ကြေးစည်တီးသည်။ || “နပသဲဝွံ အဲၜုၚ်ဂစိုတ်သၟိၚ်ဝွံရ။” (ဇ—၃၄၇။ အစွောံ။) = “ဤသံချောင်းဖြင့် မင်းအား ရိုက်သတ်အံ့။” || “ဟာဲကောန်ၚာ်တံ၊ ဗှ်ေတံလ္ပၜုၚ်ဇြုံဂှ် ဇၚ်ဍေံရ။” (ဇ—၃၈၆။အစွောံ။) = “ဟယ်ကလေးတို့၊ ထိုမြွေကို သင်တို့မရိုက်ကြကုန်လင့်၊ သူ့ဖာသာရှိပါစေ။”')
,(15758,3,4,'ရိုက်ပုတ်သည်။ ရိုက်နှက်သည်။',NULL)
,(15759,3,4,'၁။ အပူရှိန်ပေးသည်။',NULL)
,(15759,3,4,'၂။ မွေးသည်။ သားမွေးသည်။','“ကောန်မ္ဂးဂှ် ယာဲဒးၜံၚ်လဝ်ရောၚ်။” = “သားသမီးကို မိခင်ကမွေးထားရသည်။”')
,(15760,3,4,'၁။ မီးလှုံသည်။','“ကၞုဲဂြိုပ်မွဲ ဍေံတ္ၜောဟ်သၟိက်ဂွံၜံၚ်ပၟတ်—။” (ဇ—၁၇၃။ အစွောံ။) = “တောမျောက်တစ်ကောင်သည် ချမ်း၍မီးလှုံချင်၏။”')
,(15760,3,4,'၂။ မီးဖွားသည်။','“မၞိဟ်ဗြဴဗြဴမ္ဂးဂှ်မၞုံဒဒိုက်မ္ဒးၜံၚ်ပၟတ်အိုတ်ရ။” = “မိန်းမတို့မည်သည် မီးဖွားရသော ဆင်းရဲခြင်းရှိကုန်၏။” || “သွက်ဂၞကျာ်သွံ၊ သ္ဂောံၜံၚ်ပၟတ်။” (လိက်ပထမဗောဓိ။ မၚ်ဍိက်လ။) = “မိဖိုရားမီးဖွားရန်အတွက်။”')
,(15761,3,4,'နေစာလှုံသည်။','“(ခမဳသဟာဲၜါဂှ်) စှ်ေဟုံဍာ်ကြုၚ်အစဳရဝတဳတုဲ တိုန်ၜံၚ်တ္ၚဲပ္ဍဲဗတဳ—။” (ဇ—၂၇၆။ အစွောံ။) = “အဆွေခင်ပွန်းရဟန်းနှစ်ယောက်တို့သည် အစီရဝတီမြစ်­ ရေဆင်းချိုးကြပြီးလျှင် သဲပြင်­ နေစာလှုံကြကုန်၏။”')
,(15762,3,1,'၁။ ချဉ်ဖတ်။','ၜိုၚ်သတ်ဂြၚ်အေက် = ကြောင်လျှာသီးချဉ်ဖတ်။ || ၜိုၚ်က = ငါးချဉ်။ || ၜိုၚ်ၚုဲ = ပုစွန်ချဉ်။')
,(15762,3,1,'၂။ ဆတ်သတ္တဝါ။','‘တ္ၜိုၚ်’ နှင့်အတူတူ။')
,(15763,3,4,'၁။ နုသည်။','“ကၟဝ်မၚ်ဂၠန်ၜတ်ဒၟံၚ်ရ။” = “မန်ကျည်းရွက်နုထွက်နေပြီ။” || “ကာလပါရမဳအဲ မတ္ၜတ်တဴဂှ်ကီုလေဝ် အဲမဂွံဝေတ်ကၠေံပူဂဵုဒမြိုဟ်ဂှ် ဂပ်ဂဝ်ထိုၚ်သးရ” ကျာ်တြဲဂး။ (ဇ—၅၃၇။ အစွောံ။) = “ငါဘုရားသည် ပါရမီနုစဉ်ကာလက ကြမ်းကြုတ်သောသူတို့ကိုဆုံးမနိုင်ခဲ့ခြင်းသည် ချီးမွမ်းဖွယ်ဖြစ်၏။”')
,(15763,3,4,'၂။ တိုင်းထွာသည်။ တိုင်းတာသည်။','“ဂွံတီဇမၠိၚ်သ္ၚိဂှ် ဒးၜတ်ကဵုပၞောန်ဇုက်ရ။” = “အိမ်၏အလျားအရှည်ကိုသိရန် မျဉ်းကြိုးဖြင့်တိုင်းတာရမည်။”')
,(15764,3,4,'တိုင်းထွာသည်။ တိုင်းတာသည်။ နှိုင်းယှဉ်သည်။','“တၠအဲဂှ် မၞုံဂုန်မၜတ်ကၞာတ်ဟွံမာန်ရောၚ်။” (ဇ—၅၃၄။ အစွောံ။) = “ငါ့ရှင်သည် မတိုင်းတာနိုင်သော ဂုဏ်ကျေးဇူးနှင့်ပြည့်စုံ၏။” || “လၟိဟ်သတ္တံဂမၠိုၚ်ဂှ် ၜတ်ကၞာတ်ဟွံမာန်ရ။” (သၠပတ်အဓါန်မသုန်။ အစွောံ။) =“သတ္တဝါတို့၏အရေအတွက်ကို ရေတွက်တိုင်းတာခြင်းငှာ မတတ်ကောင်း။”')
,(15765,3,4,'နုနယ်သည်။ ပျော့ပျောင်းသည်။ နူးညံ့သည်။','“တဲသၟတ်ဂှ် ၜတ်သကတ်လောန်သန်။” (ဇ—၃၅၈။ အစွောံ။) = “ကလေးငယ်၏လက်သည် နုနယ်နူးညံ့၏။” || “နတဲဂၞကျာ် ညံၚ်လပှ်စိၚ်ဨရာဝိုန် မဍိုန်ၜတ်တကတ်တဴဂှ် မိန်ကေတ်အဲတုဲ—။” (ဇ—၃၆ဝ။ အစွောံ။) = “ဧရာဝဏ်ဆင်နှာမောင်းကဲ့သို့ နူးညံ့ပျော့ပျောင်းသော မိဖုရား၏လက်ဖြင့် ငါ့ကိုပွေ့ချီ၍—။” || “(သၟတ်ဗြဴဂှ်) မၞုံဇကုမတ္ၜတ်တကတ်လောန်ရောၚ်။” (ဇ—၅၂၆။ အစွောံ။) = “ထိုမိန်းမပျိုသည် နူးညံ့ပျော့ပျောင်းသောကိုယ်ရှိ၏။” || “ရုပ်သာ်ၝောံဂှ် ဂေါဝ်ဂပ်တ္ၜတ်တကတ်ဍိုန်ညံကွေံရ။ စိုတ်ၝောံဂှ် ကြံၚ်ညံၚ်တၟံလးကီုသွံၝောံ။” (ဇ—၅၃၁။ အစွောံ။) =“ရှင်မ၊ သင်၏ရုပ်ရည်သည် လှပတင့်တယ်၍ နူးညံ့ပျော့ပျောင်းလှ၏။ သင်၏စိတ်သည်ကားကျောက်ဖျာကဲ့သို့ အလွန်မာကျောပါလား။”')
,(15766,3,4,'ခြေရာတိုင်းသည်။ အန်တုသည်။',NULL)
,(15767,3,4,'နှိုင်းယှဉ်သည်။ အန်တုသည်။',NULL)
,(15768,3,4,'ချိန်တွယ်သည်။ တိုင်းတာသည်။','“လဗြဴဂှ် ကောန်လေဝ်ချိုတ် သ္ၚိလေဝ်တူအာ ဒှ်လၞီလၞာ်ဇၞော်လောန် ဒဒိုက်စိုတ် ၜတ်ဗၞတ်ဟွံမာန်ရ။” = “အဖွားအိုသည် သားလည်းသေ အိမ်လည်းမီးလောင်၊ မတိုင်းတာနိုင်လောက်အောင် စိတ်သောကဖြစ်၏။”')
,(15769,3,3,'တင့်တယ်သော။ လှပသော။','“သလးဂဗ္ဘ၊ ရုပ္ပၜတ်သောၚ်။ကောန်မိမွဲတောင်၊ ၜတ်သောၚ်စရာဲ။” (လိက်သၟိၚ်အသး။ နန္ဒသာရ။) = “အဆင်းအသရေတင့်တယ်သောသားကို ဖွားမြင်၏။” || “မိကညာဏဳ၊ ကျာ်သြဳၜတ်သောၚ်။” (လိက်ကကၠာ်။ကောန်ဍး။) = “ကျက်သရေရှိတင့်တယ်သော ပျိုကညာမယ်။”')
,(15770,3,3,'၁။ (အရွယ်) နုပျိုသော။ ပျိုမျစ်သော။','“အဇကောန်ဒေဝတဴဗြဴအဆေဝ်သွဝ်ကီု ဇကုဂေါဝ်ဂပ်တ္ၜတ်သြဴလောန်။” (ဇ—၅၂၃။ အစွောံ။) = “နတ်သမီးကဲ့သို့တင့်တယ်နုပျိုသောကိုယ်ရှိ၏။” || “ယွံကောန်၊ မဂှ် မၞုံကဵုရုပ်သာ်တ္ၜတ်သြဴရောၚ်ကောန်။” (ဇ—၅၃၇။ အစွောံ။) = “ချစ်သား၊ သင်သည် နုပျိုသောရုပ်အဆင်းရှိ၏။” || “ဂေါပ်ဂပ်ဂ္ညိဂၠဴ၊ ၜတ်သြဴရုပ္ပ။” (လိက်ဟတ္ထိပါလ။ အစွောံ။) = “ရုပ်အဆင်းနုပျိုလှပတင့်တယ်သည်။”')
,(15770,3,3,'၂။ (မြက်၊သစ်ပင်စသည်) စိမ်းနုသော။','“ကၟတ်တ္ၜတ်သြဴမတိုန်ဂှ်နွံ။” (ဇ—၁၅၇။ အစွောံ။) = “နုကုန်၊စိမ်းညိုကုန်သော မြက်တို့သည် ပေါက်ရောက်ကုန်၏။” (ညောင်ကန်)')
,(15771,3,4,'၁။ တိုးဝှေ့သည်။ တိုးကြိတ်သည်။','“(မၞိဟ်ဂၠိုၚ်လောန်) ပ္ဍဲတရၚ်ဂှ် တိတ်အာဟွံလတ်တုဲ ၜေတ်တိတ်ရၚ်သ္ကံရ။” (ဇ—စန္ဒကုမာ။ အစွောံ။) = “လူများလွန်း၍ တံခါးပေါက်မှထွက်ရန်မဆံ့သဖြင့် တိုးဝှေ့ထွက်ကြကုန်၏။” || “ဆုနွံတဴကၠေတ်၊ ဒးၜေတ်အာသၟတ်။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “သစ်ပင်များစိပ်စွာပေါက်ရောက်သဖြင့် တိုးဝှေ့၍သွားရ၏။”')
,(15771,3,4,'၂။ ကျဉ်းသည်။ ကျဉ်းကျပ်သည်။','“ဖိုၚ်ဖဴဏအ် ၜေတ်အာညိရ။” = “ဤမီးဖိုချောင်သည် အနည်းငယ်ကျဉ်းကျပ်နေသည်။”')
,(15772,3,4,'တိုးဝှေ့ထိတိုက်သည်။',NULL)
,(15773,3,4,'တိုးကြိတ်သည်။ ပြည့်ကျပ်သည်။','“ဒေဝတဴတံဂမၠိုၚ် ကၠုၚ်ဗဵုသဗ္ဗညု ၜေတ်ဂၠေတ်ညးသ္ကံ။” (ပြကိုဟ်ဂဝမ္ပတိ) = “နတ်အပေါင်းတို့သည် မြတ်စွာဘုရားကို လာရောက်ဖူးမျှော်ကြရာ ကြိတ်ကြိတ်တိုးနေ၏။”')
,(15774,3,4,'၁။ ဆွဲထုတ်သည်။ ဆွဲနုတ်သည်။','ၜေါတ်သ္ဇၚ် = ဓါးရှည်ကိုဆွဲထုတ်သည်။ || “ယြဴပူဂဵုမွဲ မၞုံတဴကဵုဂစုက်ဂှ်ဒှ်တုဲ ရဴညးမဂွံၜေါတ်ကၠေံဂစုက်ဂှ်ကီု။” (ဇ—၃၇၂။ အစွောံ။) = “ငြောင့်စူးသောသူအား ထိုဆူးငြောင့်ကို ဆွဲနုတ်ပစ်သကဲ့သို့။”')
,(15774,3,4,'၂။ ထွေးထုတ်သည်။','“ယွံမၞးတံ၊ မၞးတံသုၚ်လ္ပၚိတ်၊ ရံၚ်ညံၚ်ဍေံဟွံညာတ်တုဲ ၜေါတ်ထောံကၠေံ။” (ဇ—၃၁။ အစွောံ။) = “အချင်းတို့၊ သင်တို့သောက်ဟန်ပြု၍ မမျိုနှင့်။ သူတို့ကိုမမြင်စေဘဲ ထွေးထုတ်ပစ်လိုက်ပါ။” || “(သုဝဏ္ဏသာံဒးလဴဂျိတုဲ) ဆီမတၟိုဟ်တိတ်ပ္ဍဲပါၚ်ဂှ် တ္ၜောတ်ထောံကၠေံတုဲ—။” (ဇ—သုဝဏ္ဏသာံ။အစွောံ။) = “သုဝဏ္ဏသာမသည် မြားချက်ထိမှန်ပြီးနောက် ပါးစပ်မှလျှံထွက်သောသွေးကို ထွေးထုတ်လိုက်၏။” || “စအးက္ၜဴပါၚ် က္ၜောတ်ပြောဟ်ထောံဍာ်။” (အကြီုရာဇာဓိရာဇ်) = “ခံတွင်းဆေးပြီးနောက် ရေကိုထွေးထုတ်လိုက်၏။”')
,(15774,3,4,'၃။ နှုတ်ခမ်းစူသည်။',NULL)
,(15775,3,4,'ခယသည်။ ဝပ်တွားသည်။','“(ဒေဝတဴဂှ်) ဇအ်သဝ်ၜေါတ်ဂၠိန် ပ္တီသၟိၚ်အိန်ရ။” (လိက်ဟတ္ထိပါလ။ အစွောံ။) = “ထိုနတ်သည် သိကြားမင်းအား ခယဝပ်တွားလျှောက်ထား၏။” || ‘ဂၠိန်ၜေါတ်’ (ကြိ) လည်းရှု။')
,(15776,3,4,'၁။ နှိုက်သည်။ ကောက်ယူသည်။','‘လ္ပၜိုတ်စသွကဵုတဲညိ။’ = ‘လက်ဖြင့် ဟင်းကိုမနှိုက်စားပါနှင့်။’ || “အဲသၟိက်စံၜတ်ဓဝ်သဳလတုဲ ကသာပ်နူဂတဵုဂှ် အဲၜိုတ်ကေတ်စံရောၚ်” ဗမၞးဂး။ (ဇ—၂၉ဝ။ အစွောံ။) = “အကျွန်ုပ်သည် သီလတရားကို စုံစမ်းလို၍ ပျဉ်မှအသပြာကို ကောက်ယူစမ်းကြည့်ပါ၏” ဟုပုဏ္ဏားဆို၏။')
,(15776,3,4,'၂။ (ပါးစပ်ထဲမှ) ထွေးထုတ်သည်။','“(ကလဏ္ဍုက တ္ၜဴပါၚ်နကဵုဍာ်တှ်တုဲ) ဍာ်တှ်တ္ၜဴပါၚ်ဂှ် ၜိုတ်စုတ်ပ္ဍဲက္ဍိုပ်ကောန်ဗြဴသေဋ္ဌဳဂှ်ရ။” (ဇ—၁၂၇။ အစွောံ။) =“ကလဏ္ဍုကသည် နို့ရည်ဖြင့်ခံတွင်းဆေးပြီး ထိုနို့ရည်ကို သူဋ္ဌေးသမီးဦးခေါင်းတွင် ထွေး၏။”')
,(15776,3,4,'၃။ (လေးမြား) ဖြောင့်အောပ်လုပ်သည်။','“သၟာကံလဴဂှ် ၜိုတ်တဴကံရ။ ကံဍေံဂှ် ဖအၚ်တဴကဵုပၟတ်တုဲ မတ်မွဲဂှ် ဗၜေက်ကၠေံတုဲ ဆမတ်မွဲဂှ် ဖျေၚ်ရံၚ်တုဲ ဍေံၜိုတ်တဴကံရ။” (ဇ—မှာဇနက်။ အစွောံ) = “ထိုလေးသမားသည် — မြားကို မီးကၚ်ပြီးလျှင် မျက်စိတစ်ဖက်ကိုမှိတ်လျက် တစ်ဖက်သောမျက်စိဖြင့်ကြည့်၍ မြားတံကို — ဖြောင့်လျက်နေလေ၏။” (မင်းပူးဦးသြဘာသ)')
,(15777,3,6,'လောက်။ မျှလောက်။','“ပြေၚ်ဏအ် ဇၞော်ၜိုတ်စိၚ်ဍောတ်ရ။” = “ဤကျွဲသည်ကားဆင်ငယ်လောက်ကြီးသည်။”')
,(15777,3,7,'သမျှ။ သလောက်။','“ၜိုတ်နွံဂှ် ကဵုဏာညးရ။” = “ရှိသမျှကို သူ့အားပေးလိုက်သည်။”')
,(15778,3,5,'ထိုလောက်။',NULL)
,(15779,3,4,'ကိုယ်ကိုဆန့်သည်။ အပျင်းဆန့်သည်။','“ကၠဂှ် က္တဵုနူသ္တိက်တုဲ ၜိုတ်ဇကု—။” (ဇ—၂၈၃။ အစွောံ။) = “ထိုကျားသည် အိပ်ရာမှထ၍ အပျင်းဆန့်၏။”')
,(15780,3,5,'ဤလောက်။',NULL)
,(15781,3,4,'ကိုယ်ကိုဆန့်သည်။ အပျင်းဆန့်သည်။','“ဗောဓိသတ် (သၟိၚ်ဇာဒိသိုၚ်) တိတ်နူဂိုဟ်တၟံထဝ် ၜိုတ်နှာတ်ဇကု လရိုက်လရုသ္ဂေဟ်ဒရံၚ်—။” (ဇ—၁၄၃။ အစွောံ။) = “ဘုရားလောင်းခြင်္သေ့မင်းသည် ရွှေဂူမှထွက်၍ အပျင်းဆန့်ခြင်း ကိုယ်ကိုလှုပ်ခါခြင်းတို့ကို ပြု၏။” || ‘ၜိုတ်ဇကု’ (ကြိ) နှင့်အတူတူ။')
,(15782,3,4,'ဖြောင့်တန်းသည်။ ဖြောင့်တန်းအောင်လုပ်သည်။',NULL)
,(15783,3,5,'အဘယ်မျှလောက်။','“ၜိုတ်လဵုကေတ်ရော။” = “အဘယ်မျှလောက်ယူမည်နည်း”')
,(15784,3,4,'အပျင်းဆန့်သည်။',NULL)
,(15785,3,4,'မေးမြန်းသည်။ အလိုက်သင့်မေးသည်။','“မိပ်စိုတ်စရိုတ်၊ ၜိုတ်သၟာန်သာသာ။” (လိက်ဇိဝှစက္က) = “ဝမ်းမြောက်ဝမ်းသာဖြစ်ကာ ညင်သာစွာမေးမြန်း၏။”')
,(15786,3,4,'ပြောကြားသည်။ ဟောသည်။','“ဒိုခ်သိုခ်ဂးမာ၊ ဇာတာညးကီု၊ ၜိုတ်ဟီုကဵုညိ။” (လောကသိဒ္ဓိ။ အစွောံ။) = “ဆင်းရဲချမ်းသာကြောင်း သူ့ဇာတာကို ဟောပေးပါ။” || “ဒၞာဲဒၞာဲအဲၜိုတ်ဟီု၊ ဝိဝိၚ်လီုမှာရာ။ လ္ပကဵုဆိတ်လှောဲ၊ တၚ်နဲဗီုပမာ။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ။ မာံရောဂေါ။) = “ကျွန်ုပ်ပြောကြားလေရာ အချက်အလက်၊ နည်းလမ်း၊ ပုံပမာများ တွေဝေမှားယွင်းခြင်း မရှိပါစေသတည်း။” || “ဒၞာဲၜိုတ်ဟီုသၟတ်၊ ဟွံဂွံဆောတ်မှာ။” (လိက်ဇိဝှစက္က) =“ဟောဆိုလိုက်တိုင်း မှန်ကန်၍မချွတ်မှား။”')
,(15787,3,4,'(ကြိုးစသည်) ကျစ်သည်။','ၜန်ဇုက် = ကြိုးကျစ်သည်။ || “တောဝ်သုတ်တၟိၜန်ရ။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “ပိုးချည်သစ်ကို ကျစ်၏။” || လီၜန် = လိမ်ကျစ်သည်။ ရောထွေးပွေလီသည်။ || ၜန်သော် = ဆံပင်ကျစ်သည်။')
,(15788,3,1,'ဓါး။ ဓါးပါး။',NULL)
,(15789,3,1,'ကျိတ်ဓါး။ (?)',NULL)
,(15790,3,1,'ဓါးမြှောင်။ (ပါဠိ—အသိပုတ္တဳ)',NULL)
,(15791,3,1,'ရဟန်းပရိက္ခရာရှစ်ပါးတွင် ပါဝင်သောသင်ဓုန်းဓါး။',NULL)
,(15792,3,1,'မောင်းချဓါး။',NULL)
,(15793,3,1,'ခေါင်းရိတ်ဓါး။',NULL)
,(15794,3,1,'ပုဏ္ဍရိက်ပန်း။',NULL)
,(15795,3,4,'တွားသွားသည်။','‘ဇြုံၜေါန်အာ။’ = ‘မြွေတွားသွားသည်။’')
,(15796,3,7,'သော်လည်း။','“ၜိုန်အဲအာဝေၚ်စိုပ်သ္ၚိညး ဟွံဆဵုကဵုညးရ။” = “သူ့အိမ်သို့ ကျွန်တော်အလည်ရောက်သော်လည်း သူနှင့်မတွေ့ပါ။”')
,(15797,3,7,'သော်လည်း။ သော်ငြားလည်း။ ဖြစ်လင့်ကစား။','“ၜိုန်တၠအဲလၟသ္ကာတ်မြဟ်တဴဂှ်ကီုလေဝ် မိၚ်တဝှ်ဓဝ်အဲတုဲ စိုတ်မဒးဍိုန်အာတုဲရ။” (ဇ—၅၃၄။ အစွောံ။) = “ကြမ်းကြုတ်သောအသင်မုဆိုးပင် ဖြစ်လင့်ကစား ငါ၏ဟောကြားချက်တရားကို နာရပြီးသည်ရှိသော်စိတ်ပျော့ပျောင်းသွားရပြီ။”')
,(15798,3,7,'သို့သော်လည်း။','“ညးဂွံလဝ်ဗွဲမဂၠိုၚ် ၜိုန်ဂှ်လေဝ် ညးဟွံပေၚ်တရိုပ်စိုတ်ဏီ။” = “များစွာသူရထားသည်။ သို့သော်လည်း သူမရောင့်ရဲမကျေနပ်သေးပါ။”')
,(15799,3,7,'သို့ပၚ်ဖြစ်သော်လည်း။ သို့ပၚ်ဖြစ်စေကာမူ။','“မိကဵုခရိတ်ကွာၚ်ကဵုအဲတုဲရ။ ၜိုန်ဂှ်လေဝ်ကဵုဒှ်ကီုရ အဲထပ်အာတ်ခရိတ်ကွာၚ်ကဵုအပါပၠန်ရောၚ်။” =“ကျွန်တော့်ကို အမေမုန့်ဖိုးပေးထားပြီးပြီ။ သို့ပၚ်ဖြစ်စေ အဖေ့ဆီမှာ ကျွန်တော်မုန့်ဖိုးထပ်တောင်းဦမည်။”')
,(15800,3,4,'ခုန်တက်သည်။ (?)','“(ဗောဓိသတ်ကတုန်) ပ္ဍဲကြဴဇာဂှ် ၜပ်ကလာဲတိုန်အာ ပဲါကၠေံဇာတုဲ ဗွဲဂတတေံဂှ် အာၜပ်တလာဲတိုန်ပၠန်။ တမ္ၚာဂှ်ညာတ်တုဲ ‘ဇာဝွံပါ်အာရဒှ်၊ကဝွံဗၠးအာရ’ ဍေံဂး။” (ဇ—၁၁၄။ အစွောံ။) = “ဘုရားလောင်းငါးသည် ကွန်၏နောက်­ အပေါ်သို့ခုန်တက်ပြီးလျှင် ကွန်ကိုရှောင်ဖယ်၍ ရှေ့သို့သွား၍ ခုန်တက်ပြန်၏။ တံငါသည်မြင်၍‘ဤကွန်သည် ပေါက်သွားသည်ဖြစ်မည်၊ ဤငါးသည်လွတ်သွားလေပြီ’ ဟုဆို၏။”')
,(15801,3,4,'(ပါးစပ်) ပိတ်သည်။','ၜိပ်ပါၚ် = ပါးစပ်ပိတ်သည်။ || “အိုတ်အလုံဍုၚ် ဗဵုဒးပေဲါတ္ၚကောန်သၟိၚ်တုဲ မတ်ဟွံဖရိပ် ပါၚ်ၜိပ်ရောမာန်။” (သၠပတ်စန္ဒဝတဳ) = “မြို့အလုံးသည် မင်းသား၏လေးအတတ်ပြပွဲကိုကြည့်ကာ မျက်တောင်လည်းမခတ် ပါးစပ်လည်းမပိတ်နိုင်ဖြစ်ကုန်၏။”')
,(15802,3,1,'ဟင်္သာငှက်။',NULL)
,(15803,3,4,'တုံးသည်။','‘မြဏအ်ၜီုအာရ။’ = ‘ဤဓါးတုံးသွားပြီ။’')
,(15804,3,4,'စောင်းသည်။ ရွဲ့သည်။','“ညးဇိၚ်လဝ် ဇၟိၚ်ၜေဲဒၟံၚ်ရ။” = “သူချုပ်ထားသည်မှာ ချုပ်ရိုးချုပ်ရာ စွေစောင်းနေသည်။” || ပါၚ်ၜေဲ = ပါးစပ်ရွဲ့သည်။ || “ဗြဴတှ်သၜဲါ တှ်ဂၠိၚ်လကဲ ဗမဴတှ်မ္ဂး မုက်ကောန်ၚာ်ဂှ် ၜေဲအာ။” (ဇ—တေမဳ။ အစွောံ။) (တှ်သၜဲါ = တှ်ဂၠိၚ်လကဲ) = “ရၚ်သားရှည်လျားတွဲကျသောမိန်းမ နို့တိုက်လျှင် ကလေး၏မျက်နှာ ရွဲ့စောင်းသွားလိမ့်မည်။”')
,(15805,3,4,'စွေစောင်းသည်။ ရွဲ့စောင်းသည်။','“ၚေက်မဂွုသ္အး — ညဳသာသၟဟ် ဟွံဂၠေံဟွံဂၠိၚ်ဟွံသိၚ်ကၠေတ်ၜေဲၜုတ်ရ။” (သုဓမ္မဒေသနာ။ ဂရိုက်သာံ။) = “သွားတို့သည် ဖြူဖွေးစင်ကြယ်ညီညာ၍ မတိုမရှည် မကျဲမစိပ် မရွဲ့မစောင်း။”')
,(15806,3,1,'၁။ ကြိမ်။','လေံၜဝ် = ကြိမ်တုတ်။ || ၜဝ်ရမ္မထာ = ရမ္မထာကြိမ်။')
,(15806,3,1,'၂။ သန့်စင်သောငွေသတ္တု။ ဘော်။',NULL)
,(15807,3,1,'ရုံးပတီသီး။','‘ၜဲကဒါတ်’ ဟုလည်းရေးသည်။')
,(15808,3,1,'ခြၚ်ဆီ။ ရိုးတွင်းခြၚ်ဆီ။ (ပါဠိ—မိဉ္ဇ)','“မိဉ္ဇက္ၜဝ်ဇုတ်ကီု၊ လဟီုပ္ဍဲပါလှိ။” (လိက်လက္ခဏာဒိပ္ပဗိန္ဒော) = “မိဉ္ဇမည်သည် ခြၚ်ဆီဖြစ်သည်ဟု ပါဠိ­ဆို၏။”')
,(15809,3,1,'၁။ ဆား။',NULL)
,(15809,3,1,'၂။ နတ်သခွားပင်။ ဗူးခါးပင်။',NULL)
,(15810,3,1,'ဆားမည်း။ (ပါဠိ—ကာလလောဏ)',NULL)
,(15811,3,4,'ဆားက လောက်တက်သည်။ (ဥပစာ) အကြီးအကဲလုပ်သူက မှားယွင်းစွာ ကျင့်ကြံပြုမူသည်။',NULL)
,(15812,3,1,'ဓာတုဗေဒဆား။ ဓာတ်ဆား။',NULL)
,(15813,3,1,'အရက်နှင့်ရောစပ်ပြုပြင်ထားသောဆား။',NULL)
,(15814,3,1,'ပျားရည်နှင့်ရောစပ်ပြုပြင်ထားသောဆား။',NULL)
,(15815,3,1,'ဝမ်းနုတ်ရန်ပြဒါးဆား။ (?) (calomel)','(ဇ—၄ဝ၆။ အစွောံ။)')
,(15816,3,1,'နွားကျင်ငယ်ရေနှင့် ရောစပ်ပြုပြင်ထားသောဆား။',NULL)
,(15817,3,1,'သိန္ဓောဆား။ (ဆေးဖက်ဝင်) (rock salt)',NULL)
,(15818,3,1,'နှမ်းဆီနှင့်ရောစပ်ပြုပြင်ထားသောဆား။',NULL)
,(15819,3,4,'ခူးသည်။','ၜှ်ပ္ကဴ = ပန်းခူးသည်။')
,(15820,3,4,'ဆွတ်ခူးသည်။','“(ပ္ဍဲဍုၚ်သွဝ်တေံဂှ်) ပ္ဍဲဆုကဝ်လဗမြိုက်ဂှ် မပ္တံကစိန်ကီု လကံက်ဂြၚ်ဗံက် — သၞေက်ထဝ်ပ္ကဴထဝ်တံဂှ် ဂိုၚ်ၜှ်ပလှ်ကေတ်တုဲ မကျိုၚ်ကျဝ်ရောၚ်။” (ဇ—၂၄၃။ အစွောံ။) = “နတ်ပြည်­ ပဒေသာပင်တို့­ လက်စွပ်လက်ကောက် ရွှေနားကပ်ရွှေပန်းတို့ကို ဆွတ်ခူးယူ၍ဆင်ယင်ရကုန်၏။”')
,(15821,3,4,'‘တ္ၜေဟ်’ ရှု။',NULL)
,(15822,3,4,'‘တ္ၜေဟ်ဂၠေဟ်’ ရှု။',NULL)
,(15823,3,4,'‘တ္ၜေဟ်လက်’ ရှု။',NULL)
,(15824,3,4,'ပြုတ်သည်။','ၜိုဟ်ပုၚ် = ဆန်ပြုတ်သည်။ || ပုၚ်ၜိုဟ် = ဆန်ပြုတ်။')
,(15825,3,4,'၁။ အေးသည်။ ချမ်းသည်။','“ပ္ဍဲဥတုမုဟ်ကျာ ၜိုဟ်တဴဗွဲမလောန်ရ။” = “ဆောင်းရာသီတွင် အလွန်ချမ်းအေးသည်။” || “ခမဳဗၠာဲဂှ် — ဘောဇိုန်မတၜိုဟ်လောန်ကီု ဘောဇိုန်မကတဴလောန်ကီု ဟွံဂွံပပြဘိုက်ရ။” (ဇ—၂ဝ၉။ အစွောံ။) = “ထိုပဥ္စင်းငယ်သည်အလွန်အေးသောဘောဇဉ်ကို၄င်း အလွန်ပူသောဘောဇဉ်ကို၄င်း မသုံးဆောင်။” || “(ဗောဓိသတ်အာတရဴကန္တာဗတဳ) တ္ၚဲပၠိုတ်တိတ္ၜောဟ် ဗ္ဂန်ကေတ်ကွဳစောတ်တုဲ ဇက်အာတဴရ။” (ဇ—၂။ အစွောံ။) = “ဘုရားလောင်းသည် သဲကန္တာရခရီးသွား၏။ နေဝင်၍ မြေသည်အေးလတ်သည်ရှိသော် လှည်းတို့ကိုတပ်၍ သွား၏။” || “ကၞုဲဂြိုပ်မွဲ ဍေံတ္ၜောဟ်သၟိက်ဂွံၜံၚ်ပၟတ်—။” (ဇ—၁၇၃။အစွောံ။) = “တောမျောက်တစ်ကောင်သည် ချမ်း၍မီးလှုံချင်၏။” || “ဍာ်မတ္ၜိုဟ်ဂှ် တြသုၚ်ရ။ပ္ဍဲသမၞိၚ်ဆုမတ္ၜိုဟ်ဂှ် ဂ္ဇံဒၟံၚ်တုဲ ပဒတဴပ္ဍဲဂြိုပ်ဝွံရ။” (ဇ—၃၁၆။ အစွောံ။) = “ပုဏ္ဏား၊ အေးမြသောရေကို သောက်လော့။ ချမ်းအေးသောသစ်ရိပ်­ထိုၚ်၍ ဤတော­နေလော့။”')
,(15825,3,4,'၂။ အေးချမ်းသည်။ ပူပန်ခြင်းကင်းသည်။','“အဲပသၟိၚ်ဂှ် သတ္တံကတဴကီု တၜိုဟ်ကီု ဍေံဟီုဇီု အဲဂွံမိၚ်ညိ”သၟိၚ်ချပ်။ (ဇ—၂၈၉။ အစွောံ။) = “ငါမင်းပြုသည်မှာ လူအပေါင်းတို့သည် ပူပန်ကုန်သလောအေးချမ်းကုန်သလော ၄င်းတို့ပြောဆိုကြသည်ကို ငါကြားလို၏” ဟုမင်းသည်ကြံ၏။')
,(15826,3,4,'နားအေးသည်။ နားအေးပါးအေးရှိသည်။',NULL)
,(15827,3,4,'စိတ်အေးငြိမ်းသည်။ စိတ်ချမ်းသာသည်။','“ဂတဝွံကောန်မရာတ်သ္ဒဟ်မၞိဟ်တုဲသ္ပသၟိၚ် သတ်တံဂမၠိုၚ်ၜိုဟ်စိုတ်အိုတ်ရ။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) =“ရှေ့အနာဂတ်­ အရှင်မင်းကြီး၏သားတော်သည် လူဖြစ်လာ၍ မင်းပြုသည်ရှိသော် သတ္တဝါအပေါင်း စိတ်အေးချမ်းသာကြကုန်လတ္တံ့။” || “သတြုဟၟဲတုဲ အိုတ်ဇၟာပ်ဍုၚ်ကွာန်ရးနဳဂီု သတ္တံမဂွံတၜိုဟ်စိုတ် မဂွံအိန်သဂီုရာၚ်ဆာဲရောၚ်။” (ဇ—၅ဝ၂။ အစွောံ။) = “ရန်သူမရှိ၍ အလုံးစုံသောမြို့ရွာတိုင်းနိုင်ငံ­ လူအပေါင်းတို့သည် စိတ်အေးချမ်းသာ၍ သာယာဝပြောကုန်၏။” || “သၟိၚ်တ္ၜိုဟ်စိုတ်စရိုတ်ရ။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “မင်းသည် စိတ်အေးငြိမ်းချမ်းသာ၏။” || “သတြုချိုတ်အာတုဲ တ္ၜိုဟ်တဴစိုတ်ရအဴ။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “ရန်သူသေသွားပါက စိတ်ချမ်းသာရ၏။”')
,(15828,3,4,'ချမ်း၍တုန်သည်။','“(ဒးဗြဲဒးကျာတုဲ) တမာတ်ဂမၠိုၚ် မတ္ၜိုဟ်ဇတဝ်တဴ။” (ဇ—၁၆၄။ အစွောံ။) = “မိုးသင့်လေသင့်၍ လင်းတများသည် ချမ်း၍ခိုက်ခိုက်တုန်၏။”')
,(15829,3,4,'ပြုတ်သုပ်သည်။','‘ၜိုဟ်ပေက်စက။’ = ‘ငါးကို ပြုတ်သုပ်၍စားသည်။’ || “(ဖျုန်ဗ္ၜေအ်ဂှ်) လ္ၚဵုစုတ်မြေက်၊ ၜိုဟ်ပေက်စပ္ညုၚ်။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “ထိုဆိတ်သားကို အချို့ငရုတ်သီးထည့်ကာ ပြုတ်သုပ်စား၏။”')
,(15830,3,4,'၁။ (အရိပ်၊ ရေစသည်) အေးမြသည်။','“သၟဝ်တၞံဇြဲသုံဂှ်သတးလးသမၞိၚ်ၜိုဟ်မိပ် (မၚ်ဗၠာဲ) သ္တိက်မံၚ်ဒၞာဲဂှ်ရ။” (ဇ—၃၆ဝ။ အစွောံ။) = “ထိုပညောင်ပင်အောက်­ မြေညီပြန့်ပြူး၍ အရိပ်ကောင်းအေးမြသဖြင့် ထိုနေရာ­ လုလင်အိပ်နေ၏။” || “လ္စမွဲတ္ၜောဟ်မိပ် မဂပ်ဂဝ်လှိၚ်စိုတ် မၞုံကဵုဒကှ်သွာ—။” (ဇ—၁၉၅။ အစွောံ။) = “အေးမြချိုမြိန်သောရေနှင့်ပြည့်စုံသော မွေ့လျော်ဖွယ်ရှိသော ကြာတို့ဖြင့်ဖုံးလွှမ်းအပ်သော တစ်ခုသောရေကန်—။”')
,(15830,3,4,'၂။ (အသံ) ချိုသာသည်။ ချိုအေးသည်။ သာယာနာပျော်ဖွယ်ဖြစ်သည်။','“ဂစေံဂမၠိုၚ်မၞုံသာ်တၞဟ်ဟ် မၞုံဗရုရမျှာၚ်ၜိုဟ်မိပ်—။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “ငှက်မျိုးပေါင်းစုံတို့သည် သာယာချိုအေးသောအသံရှိကုန်၏။”')
,(15831,3,4,'နားငြီးသည်။','“ၜိုဟ်ရိုဟ်သ္ကေဝ်ကတောဝ် လၞုဟ်ကလၚ်ဂစေံတေဝ်တောဝ်ဝွံကွေံရောၚ်” ညးဂမၠိုၚ်ဂး။ (ဇ—၂၆၉။ အစွောံ။) = “တီတီတွတ်ငှက်သံသည် နားငြီးဖွယ် နားကလောဖွယ် မကြားချင်ဖွယ်ဖြစ်၏။” || “ဖံဒုတြဘိ၊ တိညံၚ်ကယျာ။ ဇၟာပ်ပေဲါဆတ္တဝ်၊ ၜိုဟ်ရိုဟ်ကတောဝ်ၜါ။” (လိက်ဇိဝှစက္က) = “ဗုံကြီးသံမြည်ဟည်းနေသည်မှာ မြေကြီးပၚ် ကွာကျသွားလုမတတ်ဖြစ်ကာ ပွဲတိုင်းသည် အမှန်တကယ်နားငြီး၏။” || “အဲၜိုဟ်ရိုဟ်သန်၊ ဇရန်ဇရာ။” (လိက်ဝါရဝေါၚ်သ။ အစွောံ။) = “အသံမြည်ဟည်းနေသည်မှာ ငါနားငြီးလှ၏။” || ‘ၜါရိုဟ်’ဟုလည်း အချို့ရေးသည်။')
,(15832,3,4,'ငြိမ်းအေးသည်။ ငြိမ်းချမ်းသည်။','“ပ္ဍဲတ္ၚဲ (သၟတ်ဂှ်) မဒှ်မၞိဟ်ဂှ် အလုံကသဳကရး ဗြဲလေဝ်ဂူ၊ စိုတ်သၟိၚ်ကီု စိုတ်မှာဇန်ဂမၠိုၚ်ကီု ၜိုဟ်လလံတဴဟေၚ်။” (ဇ—တေမဳ။ အစွောံ။) = “ထိုသူငယ်ဖွားသောနေ့­ အလုံးစုံသောကာသိတိုင်းဝယ် မိုးသည်လည်းရွာ၏။ မင်း၏စိတ်နှလုံးသည်၄င်း တိုင်းသူပြည်သားများ၏ စိတ်နှလုံးတို့သည်၄င်း အေးချမ်းကုန်၏။” || “အဲမၞုံစိုတ်မတ္ၜိုဟ်လလံ ဟွံမွဲကဵုဓဝ်စံၚ်တူတုဲရကောန်။” (ဇ—၃၅၂။ အစွောံ။) = “ချစ်သား၊ ငါသည်ငြိမ်းချမ်းသောစိတ်ရှိပြီ။ ပူပန်သောကမရှိတော့ပြီ။”')
,(15833,3,4,'(ရေ) အေးမြကြည်လင်သည်။','“ဍာ်မတ္ၜိုဟ်သ္ဇုၚ်ဂှ် ဍေံဂွံသုၚ်တုဲ—။” (ဇ—၄၁၈။ အစွောံ။) = “အေးမြကြည်လင်သောရေကို သောက်ရ၍—။”')
,(15834,3,4,'အေးချမ်းသည်။','“ပ္ဍဲကွာန်ပိုဲ ကမၠတ်ဒမၠဟွံမွဲ ၜိုဟ်သြိုဟ်တဴဗွဲမလောန်ရ။” = “ကျွန်တော်တို့ရွာတွင် သူခိုးဓါးပြမရှိ၊ အလွန်အေးချမ်းသာယာသည်။” || “သတ္တံၜိုဟ်သြိုဟ်ရာၚ်ဆာဲတဴ။” (ရာဇာဝၚ်အၚ်ဝ—ဟံသာဝတဳ) = “လူအပေါင်းတို့ အေးချမ်းသာယာသည်။” || “ကြဝိတ်ဒက်ဒေါန်၊ တ္ၜိုဟ်သြိုဟ်လောန်ဗၞတ်။” (လိက်သောဝါနနဟောၚ်) = “ကရဝိတ်တွန်ကျူးနေသည်မှာ အလွန်သာယာအေးချမ်း၏။”')
,(15835,3,3,'(ပုံပျက်အောင်) ပြားသော။ ပိန်ချိုင့်သော။','‘ညးမၞုံမုဟ်မၜေအ်။’ = ‘နှာခေါင်းပြားသောသူ။’ || “စေဝ်ဂှ် စိၚ်လိုန်ထောံၜေအ်အာရ။” = “ထိုပုံးကို ဆင်နင်းလိုက်၍ ပိန်ချိုင့်ပြားသွားပြီ။”')
,(15836,3,1,'သုံးဆဲ့ငါးလုံးမြောက်မွန်ဗျည်း။',NULL)
,(15837,3,16,'မင်း။ နင်။ (အဆင့်နိမ့်သူအမျိုးသားနှင့် သုံးသောနာမ်စား။)','“ၝသ္ဂောံတီတဲအဲရ။” =“ငါ့လက်စွမ်းကို မင်းသိရလိမ့်မည်။”')
,(15838,3,1,'အဖေ။ ဖခင်။ အဘ။','“ပ္ဍဲကာလဂှ် ၝဗောဓိသတ်သ္တိက်ဒၟံၚ် ပ္ဍဲဂတဵုဇြပ်ရ။” (ဇ—၁၅၅။အစွောံ။) = “ထိုအခါ­ ဘုရားလောင်း၏အဘသည် အင်းပျဉ်­လျောင်း၏။” (ညောင်ကန်)')
,(15839,3,16,'၁။ ဒီအကောင်။','“ၝဏအ်ဟွံချိုတ်၊ စိုတ်ပိုဲဟွံတန်။” (လိက်သောဝိန်ဇဲယ။မာံရောဂေါ။) = “ဒီကောင်မသေလျှင် ငါတို့စိတ်မကျေနပ်။”')
,(15839,3,16,'၂။ ဒီဟာ။ ဒီဥစ္စာ။','“ပၞောဝ်ဂၞိန်ၜါဂတှ်ေဏအ် အဲဒးစိုတ်ၝဏအ်။” = “ဒီထဘီနှစ်ထည်အနက် ဒီဟာ || ဒီဥစ္စာကို ငါကြိုက်ပါသည်။”')
,(15840,3,16,'ဟိုဟာ။ ဟိုဥစ္စာ။','“အဲဟွံဒးစိုတ်ၝဏအ်၊ အဲဒးစိုတ်ၝတေံ။” = “ဒီဟာကို ငါမကြိုက်၊ ဟိုဟာကို ငါကြိုက်သည်။”')
,(15841,3,16,'ဘယ်ဟာ။ ဘယ်ဥစ္စာ။','“ပၞောဝ်ပလောအ်ၜါဂတှ်ေဏအ် ၝလဵုဗှ်ေဒးစိုတ်ရော။” = “ဒီအင်းကျီနှစ်ထည်အနက် ဘယ်ဟာ || ဘယ်ဥစ္စာကို နၚ်ကြိုက်ပါသလဲ။”')
,(15842,3,1,'အစ်မ။','“ၝဲတရဴမိၚ်၊ လဟိၚ်စိုတ်ပ္ဍဲ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “အစ်မ ခြောက်ယောက်တို့ ကြားသည်ရှိသော် စိတ်ထဲမှာ ကျိတ်၍ပျော်၏။”')
,(15843,3,1,'ကလေးထိန်းအမျိုးသမီး။ အထိန်းတော်မ။','“ကောန်ဗြဴသေဋ္ဌဳမွဲဂှ် ညာတ်ဂၠဴဥဿဘမွဲ မနွံသဗအ်မသၠုၚ်လောန်တုဲ — ဍေံသၟာန်မိမိန်ၝဲဂမာဍေံဂှ်ရ။” (ဇ—၂၃၂။ အစွောံ။) = “တစ်ယောက်သောသူဋ္ဌေးသမီးသည် မြင့်သောလဘို့ရှိသော နွားဥသဘကိုမြင်၍ အထိန်းတော်မအားမေး၏။” || “(သၟိၚ်တုန်) ကောန်ဇကုပြဘာဝတဳဂှ် ကဵုကျိုၚ်ကျဝ်တုဲ ပဂကောံကဵုမိမိန်ၝဲဂမာဂှ်တုဲ ကဵုပြာပ်တိတ်ကၠုၚ်ရ။” (ဇ—၅၃၁။ အစွောံ။) = “မင်းသည် သမီးတော်ပဘာဝတီကို ဆင်ယင်စေပြီးလျှင် အထိန်းတော်မတို့နှင့် အတူတကွထွက်လာစေ၏။” || (မိမိန် = ၝဲဂမာ) || (မှတ်ချက်။ အထိန်းတော်သည် များသောအားဖြင့် မိန်းမဖြစ်သည်။ ယောကျာ်းဖြစ်သော် ‘ကောဂမာ’ ဟုသုံးသည်။) || ‘ကောဂမာ’ လည်းရှု။')
,(15844,3,1,'မရီး။ အစ်ကို၏ဇနီး။','‘ဗာဲ’ (န) နှင့်အတူတူ။')
,(15845,3,1,'အထိန်းတော်မ။',NULL)
,(15846,3,9,'(ဝါကျနောက်ဆက်) ကွာ။ ကွယ်။ ဟယ်။','ကၠုၚ်လေဝ်ၝာဲ = လာလေကွယ်။ || လ္ပပညိၝာဲ = မလုပ်ပါနှင့်ကွယ်။')
,(15847,3,1,'၁။ အဆင့်နိမ့်သူအမျိုးသမီးကို ရင်းနှီးစွာရည်ညွှန်းရာတွင် သုံးသောအခေါ်အဝေါ်။ ကောင်မ။',NULL)
,(15847,3,1,'၂။ အမျိုးသမီးကို ဆဲရေးရာတွင်လည်း သုံးလေ့ရှိသောအခေါ်အဝေါ်။','ၝုဲဏအ် = သည်ကောင်မ။')
,(15848,3,16,'ညည်း။ (မိမိအောက်ငယ်သောမိန်းမကို ခေါ်ဝေါ်သောစကား။)','“တြုံဗှ်ေတံချိုတ်အာမ္ဂး ဗှ်ေတံဟွံဂွံတြုံရ။ အဲဟွံကေတ်ၝိုယ်တံရ။” (ဇ—၅၃၆။ အစွောံ။) = “နင်တို့လင်သေသွားလျှင် နင်တို့လင်မရတော့ပါ။ ညည်းတို့ကို ငါမယူ။” || “က္တဵုရၝိုဲတအ်၊ တၟအ်ညးအဲ။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “ညည်းတို့အားလုံး ထကြလော့။”')
,(15849,3,1,'၁။ အမ။','ဂၠဴၝောံ = နွားမ။ (မှတ်ချက်။ မွန်စာပေဟောင်းတွင် ‘အမ’ ကို‘ဗြဴ’ ဟူ၍အသုံးများသည် (ဥပမာ — ဂၠဴဗြဴ = နွာမး။ || ကၠဵုဗြဴ = ခွေးမ။))')
,(15849,3,1,'၂။ ဇနီးမယားကိုချစ်စနိုးခေါ်ဆိုသောစကား။ ရှင်မ။','“ယွံၝောံ၊ သဟာဲပိုဲဗျဵုပုၚ်ရ။ ၝောံအာစဳရေၚ်ပုၚ်သွပြဟ်ညိ။” (ဇ—၃ဝ၂။ အစွောံ။) = “ရှင်မ၊ ငါတို့အဆွေခင်ပွန်းသည် ထမင်းဆာပြီ။ ရှင်မ၊သွား၍ ထမင်းဟင်းတို့ကို အမြန်စီရင်လော့။”')
,(15849,3,1,'၃။ အရွယ်ရောက်ပြီးသောလူကို ခေါ်ဆိုရာတွင်သုံးသည်။','ၝောံမၞိဟ် = လူကြီး။ (ယောကျာ်းမိန်းမအပါအဝင်)')
,(15849,3,1,'၄။ အရွယ်ရောက်ပြီးသော တိရစ္ဆာန်ကိုခေါ်ဆိုရာတွင်သုံးသည်။','ၝောံဂၠဴ = နွားကြီး (နွားထီးနွားမအပါအဝင်) || ၝောံဒြာဲကဵုကောန်ဒြာဲ= သမင်မကြီးနှင့်သမင်သားလေး။ || ၝောံဂၠဴကၟက် = နွားကြီးအထီး။')
,(15849,3,1,'၅။ မိခင်ဖြစ်သောတိရစ္ဆာန်။','“ယွံဣသိ၊ တၠလွဳလဝ်ကောန်စိၚ်ကၟက်မွဲကွေံဟာ။” “ၝောံဍေံချိုတ်အာတုဲ အဲဍိက်လွဳလဝ်ဍေံကွေံရ။” (ဇ—၁၆၁။ အစွောံ။) = “ရသေ့၊ သင်သည် ဆင်ငယ်ကိုမွေး၏ဟူ၍ ငါကြားရသည်မှန်သလော။” “အမိသေသော ဆင်ငယ်တစီးကို မွေး၏။” (ညောင်ကန်) || “ၝောံဂၠဴဂှ် သလးကောန်တြုံမွဲရ။” (ဇ—၃၄၉။ အစွောံ။) = “နွားမကြီးသည် သားထီးတစ်ကောင်ကိုဖွား၏။”')
,(15849,3,1,'၆။ ကြီးသောအရွယ်အစား။','ၝောံအှ်ော = ထင်းတုံးကြီး။ || “ဗောဓိသတ်ပိုဲကေတ်နၚ် ၝောံအှ်ောတမ္ၚူမွဲ စုတ်လဝ်ပၟတ်တုဲ—။” (ဇ—၂၅ဝ။ အစွောံ။) = “ဘုရားလောင်းသည် (ဖြောင့်သော) ကြီးစွာသော ထင်းတုံးတို့ကိုဆောင်၍ မီးညှိ၍—။” (ညောင်ကန်)')
,(15849,3,9,'တစ်မ။',NULL)
,(15849,3,1,'၁။ အမ။','ဗြဲမွဲၝောံ = မိုးတစ်မ။')
,(15850,3,11,'(န) ၁။ မကိုဋ်။ (ဘုရင်စသောမြင့်မြတ်သူတို့ ဆောင်းသည့်ဦးခေါင်းတန်ဆာ။)','“ဗောဓိသတ် (သၟိၚ်ပဒုမ) သလိုက်ၝောံကိုတ်၊ ဗြကၞေၚ်၊ ဗသေၚ်၊ တဝ်စရှ်တုဲ—။” (ဇ—၁၉၃။ အစွောံ။) = “ဘုရားလောင်းပဒုမမင်းသည် မကိုဋ်၊ နဖူးတန်ဆာ၊ သရဖူ၊ဦးဆောက်ပန်းတို့ကို တန်ဆာဆင်ယင်ပြီးသော်—။”')
,(15850,3,11,'(န) ၂။ စေတီအထွတ်အထိပ် အစိတ်အပိုင်းတစ်ခု။','“တလညးဂွံယိုက်ၝောံကိုတ် ဂွံစုတ်ဓုပ်ပြကာက္ဍိုၚ်။” (ရာဇာဝံသသံခိပ်။ အစွောံ။)')
,(15850,3,11,'(န) ၃။ (ဥပစာ) အထွတ်အမြတ်။','“သၟိၚ်မဒှ်ၝောံကိုတ်ဇန်။” = “လူတို့၏အထွတ်အမြတ်မကိုဋ်ဖြစ်သောမင်း။”')
,(15851,3,1,'ခက်မ။ သစ်ပင်၏အကိုင်းကြီး။',NULL)
,(15852,3,1,'ခက်မငါးဖြာ။ ခြေနှစ်ချောင်း၊ လက်နှစ်ချောင်းနှင့် ဦးခေါင်းအၚ်္ဂါအစိတ်အပိုင်း။','“အကြီုပ္ဍဲဂဝ်ဂၞဴမိ၊ ပတိသန္ဓိဂဝ်ဂှ်။ —— က္ဍိုပ်ဇိုၚ်တဲတိတ်ဗျာၚ်၊ ၝောံကၞာၚ်မသုန်ဒှ်။” (လိက်လက္ခဏာဒိပ္ပဗိန္ဒော) = “အမိဝမ်းအိမ်­ ပဋိသန္ဓေတည်သောအကြောင်းကို ဆိုရသော်ခေါင်း၊ ခြေ၊ လက် ထွက်လာကာ ခက်မငါးဖြာဖြစ်တည်၏။”')
,(15853,3,1,'ထွန်တုံး။',NULL)
,(15854,3,1,'လမ်းမ။ လမ်းမကြီး။',NULL)
,(15855,3,4,'မိခင်သွားရာနောက်သို့ သားသမီးများ (သို့မဟုတ်) တိရစ္ဆာန်ကလေးများ အစုလိုက် တကောက်ကောက်လိုက်သည်။',NULL)
,(15856,3,1,'ခြေမ။',NULL)
,(15857,3,1,'မြို့မိမြို့ဖ။ မြို့ရွာ၏ဂုဏ်သရေရှိလူကြီးမင်းများ။',NULL)
,(15858,3,1,'၁။ လက်မ။ (လက်ချောင်း)',NULL)
,(15858,3,1,'၂။ တစ်လက်မအတိုင်းအတာ။','မသုန်ၝောံတဲ = ငါးလက်မ။')
,(15859,3,1,'ရာထူးရှိသောအမျိုးသမီး။ (ရှေးသုံး)',NULL)
,(15860,3,1,'အမတ်ကတော်။ မှူးမတ်ကတော်။',NULL)
,(15861,3,1,'၁။ အရွယ်ရောက်ပြီးသူ။ လူကြီး။',NULL)
,(15861,3,1,'၂။ အကြီးအကဲ။','ၝောံမၞိဟ်ကွာန် = ရွာသူကြီး။ || ၝောံမၞိဟ်အရာပ် = ရပ်ကွက်လူကြီး။')
,(15862,3,1,'လူကြီးလူကောင်း။ ရပ်မိရပ်ဖ။ မြို့မိမြို့ဖ။',NULL)
,(15863,3,1,'အဖွဲ့ခေါင်းဆောင်။ အသင်းခေါင်းဆောင်။','“ၝောအ်ရဲဗှ်ေတအ် ညးဂှ်ရော။” = “မင်းတို့အဖွဲ့ခေါင်းဆောင် ဘယ်သူလဲ။”')
,(15864,3,1,'ပျားဘုရင်မ။','“ညံၚ်သာဲမသက္ကုၝောံကီု။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “ပျားဘုရင်မ၊မရှိသော ပျားအုံကဲ့သို့။”')
,(15865,3,1,'အိမ်ခန်းမဆောင်။','“တံၚ်တဲတြုံသွံ၊ လုပ်ၝောံသ္ၚိပၠန်။” (လိက်ဇိဝှစက္က) = “ယောကျာ်း၏လက်ကိုဆွဲကာ အိမ်ခန်းမဆောင်သို့ဝၚ်၏။”')
,(15866,3,1,'(ဆန်ကွဲဆန်ကျိုးမဟုတ်သော) ဆန်ကောင်း။ ဆန်ရင်း။','“ဆၝောံသ္ၚုသက်က် ဂြိုက်ကေတ်တုဲ တောံပုၚ်ရ။ ဒေါဝ်သ္ၚုဂှ် တောံယာဂု၊ ကဏန်သ္ၚုဂှ်ပကွာၚ်။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “ဆုံ­ဖြူစင်စွာဖွပ်သဖြင့် ဆန်ရင်းကို ထမင်းချက်၏။ ဆန်လတ်ကို ယာဂုကျို၏။ဆန်ခွဲကိုကား — မုန့်ကြွပ်လုပ်၏။” (မင်းပူးဦးသြဘာသ) || ‘တမ်သ္ၚု’ (န) လည်းရှု။')
;